import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, RenderSurface, SessionContextUsage, SessionRateLimit } from 'claude-code'

import type { Step } from '../types'
import {
  HANDOFF_PROMPT,
  cacheOf,
  continuation,
  forecastFor,
  limitLabel,
  orderLimits,
  savedTurn,
  short,
  span,
  ttlOf,
  until,
  usageColor,
} from './lib'

const STORE_HANDOFF = 'handoff'
// The last turn, kept so a reload of the mod does not lose whether the cache is warm.
const STORE_LAST = 'last'
// How often the countdowns move.
const HEARTBEAT_MS = 15_000

const context = atom({ plugin: 'usage-weather', key: 'context' } as const, null)
const limits = atom({ plugin: 'usage-weather', key: 'limits' } as const, [])
const last = atom({ plugin: 'usage-weather', key: 'last' } as const, null)
const beat = atom({ plugin: 'usage-weather', key: 'beat' } as const, 0)
const owner = atom({ plugin: 'usage-weather', key: 'owner' } as const, '')
const step = atom({ plugin: 'usage-weather', key: 'step' } as const, 'idle')
const note = atom({ plugin: 'usage-weather', key: 'note' } as const, '')

type Figures = { context: SessionContextUsage; rateLimits: readonly SessionRateLimit[] }

// Takes in what the engine measured: the window's fill and the account's limits.
async function apply($: EngineInterface, figures: Figures) {
  const { tokens, window } = figures.context
  if (tokens !== undefined && tokens > 0 && window > 0) {
    const percent = Math.round(figures.context.percent ?? (tokens / window) * 100)
    await update($, context, () => ({ tokens, window, percent }))
  }
  if (figures.rateLimits.length > 0) {
    const next = figures.rateLimits.map(l => ({ kind: l.kind, percentUsed: l.percentUsed, resetsAt: l.resetsAt }))
    await update($, limits, () => next)
  }
}

async function fail($: EngineInterface, why: string) {
  await update($, note, () => why)
  await update($, step, () => 'idle')
  void $.ui.toast(why)
}

// Summarizes the session, clears it and hands the summary to the fresh one.
// Nothing is cleared until the summary is in hand, and if the clear or the
// hand-over fails the summary goes to the clipboard so it is not lost.
async function clearAndContinue($: EngineInterface, surface: RenderSurface) {
  await update($, note, () => '')
  await update($, step, () => 'summarizing')
  let handoff = ''
  try {
    const r = await $.model.fork({ prompt: HANDOFF_PROMPT })
    if (!r.isAnswered) {
      await fail($, r.reason === 'nothing-to-fork' ? 'Nothing to carry over yet.' : `Could not summarize the session (${r.reason}).`)

      return
    }
    handoff = r.text.trim()
    if (handoff === '') {
      await fail($, 'The summary came back empty, so nothing was cleared.')

      return
    }
    await $.store.set(STORE_HANDOFF, { text: handoff, at: await $.clock.now() })
    await update($, step, () => 'clearing')
    await $.command.run({ command: 'clear' })
    await update($, step, () => 'continuing')
    await $.prompt.submit({ text: continuation(handoff), asUser: true })
    await update($, step, () => 'idle')
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error)
    const copied = handoff !== '' && (await $.ui.copy({ text: handoff, surface }).catch(() => undefined))?.isCopied === true
    await fail($, copied ? `Clear & continue stopped (${reason}). The summary is on your clipboard.` : `Clear & continue stopped (${reason}).`)
  }
}

export const register: Register = (on, options) => {
  const ttlMs = ttlOf(options.cacheTtl)
  const instance = Math.random().toString(36).slice(2)

  on('session.start', async ($, e, next) => {
    // The heartbeat moves the countdowns. A reload starts another and takes
    // the ownership, so the one left from before stops at its next beat.
    await update($, owner, () => instance)
    const timer = $.clock.every(HEARTBEAT_MS, () => {
      void read($, owner)
        .then(async who => {
          if (who !== instance) {
            timer.cancel()

            return
          }
          await update($, beat, n => n + 1)
        })
        .catch(() => timer.cancel())
    })
    // A reload drops a Clear & continue that was under way.
    await update($, step, () => 'idle')
    // The last turn outlives a reload, so the cache stays known.
    const saved = savedTurn(await $.store.get(STORE_LAST), await $.session.id())
    if (saved !== null) {
      await update($, last, was => was ?? saved)
    }
    try {
      await apply($, await $.session.usage())
    } catch {
      // No reading yet; the first measurement fills the band.
    }

    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    await apply($, e)

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) {
      // The next turn retires the last failure's line.
      await update($, note, () => '')
    }
    if (e.agentId === undefined && e.usage !== undefined) {
      const at = await $.clock.now()
      const { cache_read_input_tokens: cached, cache_creation_input_tokens: wrote, input_tokens: fresh } = e.usage
      await update($, last, () => ({ at, read: cached, wrote, fresh }))
      await $.store.set(STORE_LAST, { sessionId: await $.session.id(), at, read: cached, wrote, fresh })
    }

    return next(e)
  })

  // /clear starts the figures over; Clear & continue's own step is left alone.
  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      await update($, context, () => null)
      await update($, last, () => null)
      await $.store.set(STORE_LAST, null)
    }

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) {
      return next(e)
    }
    const window = await read($, context)
    const windows = orderLimits(await read($, limits))
    const turn = await read($, last)
    const doing: Step = await read($, step)
    const why = await read($, note)
    // Read for the subscription: each beat redraws the countdowns.
    await read($, beat)
    if (window === null && windows.length === 0 && turn === null) {
      return next(e)
    }
    const { Box, Text, Button } = $.ui.resolve(e)
    const now = await $.clock.now()
    const weather = window === null ? undefined : forecastFor(window.percent)
    const cache = cacheOf(turn, now, ttlMs)
    const isIdle = doing === 'idle'
    const canClear = isIdle && !e.props.isWorking && (window !== null || turn !== null)

    // One quiet line. Every child sits straight in the row: a fragment would be
    // drawn as a column and break the line. Clearing takes the whole line while
    // it asks and works.
    return (
      <Box flexDirection="column" paddingX={1}>
        <Box flexDirection="row" flexWrap="wrap" columnGap={2} alignItems="center">
          {isIdle && window !== null && weather !== undefined && (
            <Box flexDirection="row" gap={1}>
              <Text color={weather.color} bold>{`${weather.icon} ${window.percent}%`}</Text>
              <Text dimColor>{`${short(window.tokens)}/${short(window.window)}`}</Text>
            </Box>
          )}
          {isIdle &&
            windows.map(w => (
              <Box flexDirection="row" gap={1}>
                <Text dimColor>{limitLabel(w.kind)}</Text>
                <Text color={usageColor(w.percentUsed)}>{`${Math.round(w.percentUsed)}%`}</Text>
                {until(w.resetsAt, now) !== '' && (
                  <Text dimColor>{`↻${until(w.resetsAt, now)}`}</Text>
                )}
              </Box>
            ))}
          {isIdle && (
            <Box flexDirection="row" gap={1}>
              <Text dimColor>cache</Text>
              {cache.state === 'warm' ? (
                <Text color="success">{`warm ${span(cache.leftMs)}`}</Text>
              ) : cache.state === 'cold' ? (
                <Text color="warning">cold</Text>
              ) : (
                <Text dimColor>–</Text>
              )}
            </Box>
          )}
          {canClear && (
            <Button key="clear-continue" label="Clear & continue" onPress={() => void update($, step, () => 'confirm')} />
          )}
          {doing === 'confirm' && <Text bold>Summarize and clear?</Text>}
          {doing === 'confirm' && (
            <Text dimColor>{cache.state === 'warm' ? 'cheap, the cache is warm' : 'costs more, the cache is cold'}</Text>
          )}
          {doing === 'confirm' && (
            <Button
              key="confirm-yes"
              variant="primary"
              label="Yes, clear"
              onPress={press => void clearAndContinue($, press.surface)}
            />
          )}
          {doing === 'confirm' && (
            <Button key="confirm-no" label="Cancel" onPress={() => void update($, step, () => 'idle')} />
          )}
          {doing === 'summarizing' && <Text color="claude">Summarizing the session…</Text>}
          {doing === 'clearing' && <Text color="claude">Clearing…</Text>}
          {doing === 'continuing' && <Text color="claude">Continuing from the summary…</Text>}
        </Box>
        {why !== '' && isIdle && <Text color="error">{why}</Text>}
      </Box>
    )
  })
}

