import type { Limit, Turn } from '../types'

// Context forecast bands, by percent of the window used. Theme colors, so the
// band follows light and dark.
const FORECAST = [
  { upTo: 25, icon: '☀', color: 'success' },
  { upTo: 50, icon: '☁', color: 'suggestion' },
  { upTo: 75, icon: '☂', color: 'warning' },
  { upTo: 90, icon: '☇', color: 'error' },
] as const
const COMPACT = { icon: '↯', color: 'error' } as const

export const forecastFor = (percent: number) => FORECAST.find(band => percent < band.upTo) ?? COMPACT

export const short = (n: number) => {
  if (n >= 1_000_000) {
    return `${(n / 1_000_000).toFixed(n % 1_000_000 === 0 ? 0 : 1)}M`
  }
  if (n >= 1_000) {
    return `${(n / 1_000).toFixed(n % 1_000 === 0 ? 0 : 1)}k`
  }

  return String(n)
}

// Green while there is room, amber as it fills, red near the limit.
export const usageColor = (percent: number) => (percent >= 85 ? 'error' : percent >= 60 ? 'warning' : 'success')

// A span as the band writes it: <1m, 45m, 2h13m, 4d 3h. Minutes round up, so
// a countdown never reads zero while time is left.
export const span = (ms: number) => {
  if (ms <= 0) {
    return ''
  }
  if (ms < 60_000) {
    return '<1m'
  }
  const minutes = Math.ceil(ms / 60_000)
  if (minutes < 60) {
    return `${minutes}m`
  }
  const hours = Math.floor(minutes / 60)
  if (hours < 24) {
    return minutes % 60 === 0 ? `${hours}h` : `${hours}h${String(minutes % 60).padStart(2, '0')}m`
  }
  const days = Math.floor(hours / 24)

  return hours % 24 === 0 ? `${days}d` : `${days}d ${hours % 24}h`
}

// Time to a window's reset; empty when it is unknown or already past.
export const until = (resetsAt: string | undefined, now: number) => {
  const at = resetsAt === undefined ? Number.NaN : Date.parse(resetsAt)

  return Number.isNaN(at) ? '' : span(at - now)
}

const LABELS: Record<string, string> = { five_hour: '5h', seven_day: 'week' }
export const limitLabel = (kind: string) => LABELS[kind] ?? kind.replace(/_/g, ' ')

// The 5-hour window first, then the week, then whatever else the account has.
export const orderLimits = (limits: readonly Limit[]) => {
  const rank = (kind: string) => (kind === 'five_hour' ? 0 : kind === 'seven_day' ? 1 : 2)

  return [...limits].sort((a, b) => rank(a.kind) - rank(b.kind))
}

export const TTL = { '5m': 5 * 60_000, '1h': 60 * 60_000 } as const
export const ttlOf = (option: unknown) => (option === '5m' ? TTL['5m'] : TTL['1h'])

// A turn as it is kept between loads, tied to the session it belongs to.
export type SavedTurn = Turn & { sessionId: string }

// What the store holds, read back as a turn of this session, or null when it
// is another session's or not a turn at all.
export const savedTurn = (value: unknown, sessionId: string): Turn | null => {
  const v = value as Partial<SavedTurn> | null
  if (v === null || typeof v !== 'object' || v.sessionId !== sessionId) {
    return null
  }
  const { at, read, wrote, fresh } = v

  return typeof at === 'number' && typeof read === 'number' && typeof wrote === 'number' && typeof fresh === 'number'
    ? { at, read, wrote, fresh }
    : null
}

export type Cache = { state: 'none' | 'cold' | 'warm'; leftMs: number; hit: number }

// Whether the prompt cache still holds the session: warm from the last
// main-thread turn until the cache lifetime has passed. `hit` is how much of
// that turn's prompt the cache served.
export const cacheOf = (last: Turn | null, now: number, ttlMs: number): Cache => {
  if (last === null || last.read + last.wrote === 0) {
    return { state: 'none', leftMs: 0, hit: 0 }
  }
  const hit = Math.round((last.read / (last.read + last.wrote + last.fresh)) * 100)
  const leftMs = last.at + ttlMs - now

  return leftMs > 0 ? { state: 'warm', leftMs, hit } : { state: 'cold', leftMs: 0, hit }
}

// What the fork writes before the conversation is cleared. It answers over
// the session's own transcript, so it needs no copy of it here.
export const HANDOFF_PROMPT = [
  'The person is about to clear this conversation and carry on in a fresh one. Write the handoff that fresh conversation will start from.',
  'Be specific and compact (under 600 words), in the language we have been speaking. Do not call tools. Write only these sections:',
  'Goal: what we are trying to achieve overall.',
  'Done: what is finished, with the file paths and commands that matter.',
  'State: where the work stands now: what is in progress, half done or running.',
  'Decisions: choices made and why, constraints, and preferences the person stated.',
  'Next: the very next steps, in order.',
  'Open: questions or approvals still needed from the person.',
].join('\n')

export const continuation = (handoff: string) =>
  [
    '[Clear & continue] The previous conversation was cleared to free context. Its handoff is below; the files on disk are as that conversation left them.',
    'Continue from "Next". If a step needs my approval or a decision, ask before doing it.',
    '<handoff>',
    handoff,
    '</handoff>',
  ].join('\n')

