// The context window as one turn left it.
export type Reading = { tokens: number; window: number; percent: number }

// A rate-limit window: `five_hour`, `seven_day`, or a gateway's `spend_limit`.
export type Limit = { kind: string; percentUsed: number; resetsAt?: string }

// The last main-thread turn: when it ended and how its prompt cache was used.
export type Turn = { at: number; read: number; wrote: number; fresh: number }

// Where Clear & continue stands.
export type Step = 'idle' | 'confirm' | 'summarizing' | 'clearing' | 'continuing'

declare module 'claude-code' {
  interface PluginState {
    'usage-weather': {
      // The window's fill as the last turn left it; null before one.
      context: Reading | null
      limits: Limit[]
      last: Turn | null
      // Ticks every few seconds so countdowns move; only its writes matter.
      beat: number
      // The module instance that owns the heartbeat; a reload hands it on.
      owner: string
      step: Step
      // Why the last Clear & continue stopped; empty otherwise.
      note: string
    }
  }
}
